/// Returns `true` if `input` reads the same forwards and backwards, ignoring
/// spaces, case, and punctuation.
///
/// Only alphanumeric characters are considered; everything else (whitespace,
/// punctuation, symbols) is skipped. Comparison is case-insensitive, including
/// for non-ASCII characters.
///
/// A string with no alphanumeric characters at all is considered a palindrome.
///
/// # Examples
///
/// ```
/// assert!(is_palindrome("A man a plan a canal Panama"));
/// assert!(!is_palindrome("hello"));
/// ```
pub fn is_palindrome(input: &str) -> bool {
    let chars: Vec<char> = input
        .chars()
        .filter(|c| c.is_alphanumeric())
        .flat_map(|c| c.to_lowercase())
        .collect();

    chars.iter().eq(chars.iter().rev())
}

/// ```
/// assert!(tdd::is_palindrome("A man a plan a canal Panama"));
/// assert!(!tdd::is_palindrome("hello"));
/// ```

