use strict; use warnings; use utf8;
binmode(STDOUT, ':encoding(UTF-8)');

# Mirror of the Rust implementation: keep alphanumeric chars, lowercase, compare to reverse
sub is_palindrome {
    my ($s) = @_;
    my @chars;
    for my $c (split //, $s) {
        push @chars, split //, lc($c) if $c =~ /\p{Alnum}/;
    }
    my @rev = reverse @chars;
    return (join('', @chars) eq join('', @rev)) ? 1 : 0;
}

my @cases = (
  ["racecar", 1],
  ["A man a plan a canal Panama", 1],
  ["hello", 0],
  ["", 1],
  ["   ", 1],
  ["!!!", 1],
  ["Was it a car or a cat I saw?", 1],
  ["No lemon, no melon", 1],
  ["ab", 0],
  ["a", 1],
  ["aa", 1],
  ["abba", 1],
  ["abcba", 1],
  ["abcab", 0],
  ["A man, a plan, a canal, Panama!", 1],
  ["12321", 1],
  ["123421", 0],
  ["Etc.; e", 0],
  ["été", 1],
  ["École", 0],
);

my $fail = 0;
for my $c (@cases) {
    my ($s, $want) = @$c;
    my $got = is_palindrome($s);
    my $ok = ($got == $want);
    $fail++ unless $ok;
    printf("%s %-35s -> %d (expected %d)\n", ($ok ? "ok  " : "FAIL"), "'" . $s . "'", $got, $want);
}
print "\nmismatches: $fail\n";
EOF
